// ============================================================================
// FreeLang StringIndex 모듈 - 정렬 배열 기반 문자열 인덱스
// ============================================================================
// 목표: 문자열 컬럼에 대해 EQ/LIKE/범위 검색 지원
// 원리:
//   1. 정렬 배열: string 키를 정렬된 순서로 저장 (B+Tree 대신 간단화)
//   2. 이진 탐색: EQ 검색은 이진 탐색으로 O(log n)
//   3. LIKE 검색: 접두어 일치는 선형 탐색 (char_at 비교)
//   4. 범위 검색: 사전식 비교로 시작/종료 위치 찾기
// 구조:
//   - StrIndexEntry, StrIndex 구조체
//   - 삽입 (유지 정렬), 검색, 범위 스캔
// ============================================================================

module index_str {
    // === 상수 ===
    const MAX_STR_ENTRIES: i32 = 1024;

    // === 에러 코드 ===
    const STR_IDX_OK:          i32 = 0;
    const STR_IDX_ERR_FULL:    i32 = 60;
    const STR_IDX_ERR_NOTFOUND: i32 = 61;

    // === 데이터 구조체 ===

    struct StrIndexEntry {
        key:    string;
        row_id: i64;
    }

    struct StrIndex {
        col_idx:     i32;
        entries:     [StrIndexEntry];
        entry_count: i32;
    }

    // === 팩토리 함수 ===

    // 새로운 문자열 인덱스 생성
    func str_index_new(col_idx: i32) -> StrIndex {
        return StrIndex{
            col_idx:     col_idx,
            entries:     make([StrIndexEntry], MAX_STR_ENTRIES),
            entry_count: 0,
        };
    }

    // === 문자열 비교 함수 ===

    // 두 문자열 비교: a < b → -1, a == b → 0, a > b → 1
    // 사전식(lexicographic) 순서로 비교
    @inline
    func str_cmp(a: string, b: string) -> i32 {
        let a_len = len(a);
        let b_len = len(b);
        let min_len = a_len;
        if b_len < min_len {
            min_len = b_len;
        }

        let i = 0;
        for i = 0; i < min_len; i = i + 1 {
            let a_ch = char_at(a, i);
            let b_ch = char_at(b, i);
            if a_ch < b_ch {
                return -1;
            }
            if a_ch > b_ch {
                return 1;
            }
        }

        if a_len < b_len {
            return -1;
        }
        if a_len > b_len {
            return 1;
        }
        return 0;
    }

    // 접두어 일치 확인
    // "hello" starts_with "he" → true
    @inline
    func str_starts_with(str: string, prefix: string) -> bool {
        let plen = len(prefix);
        let slen = len(str);
        if plen > slen {
            return false;
        }
        let i = 0;
        for i = 0; i < plen; i = i + 1 {
            if char_at(str, i) != char_at(prefix, i) {
                return false;
            }
        }
        return true;
    }

    // === 삽입 함수 (정렬 유지) ===

    // 키-로우 쌍을 인덱스에 삽입 (정렬 순서 유지)
    // 실패 시 STR_IDX_ERR_FULL 반환
    func (si: *StrIndex) str_insert(key: string, row_id: i64) -> i32 {
        if si.entry_count >= MAX_STR_ENTRIES {
            return STR_IDX_ERR_FULL;
        }

        // 삽입 위치 찾기 (정렬 순서 유지)
        let pos = 0;
        let i = 0;
        for i = 0; i < si.entry_count; i = i + 1 {
            let cmp = str_cmp(key, si.entries[i].key);
            if cmp < 0 {
                pos = i;
                break;
            }
            pos = i + 1;
        }

        // 배열 우측 시프트 (pos 위치 뒤로 모든 원소 이동)
        let j = si.entry_count;
        for j > pos {
            si.entries[j] = si.entries[j - 1];
            j = j - 1;
        }

        // 새 엔트리 삽입
        si.entries[pos] = StrIndexEntry{
            key:    key,
            row_id: row_id,
        };
        si.entry_count = si.entry_count + 1;
        return STR_IDX_OK;
    }

    // === 검색 함수 ===

    // EQ 검색: 정확 일치하는 키 검색
    // 반환: (row_id, 찾음 여부)
    func (si: *StrIndex) str_search(key: string) -> (i64, bool) {
        let i = 0;
        for i = 0; i < si.entry_count; i = i + 1 {
            if si.entries[i].key == key {
                return (si.entries[i].row_id, true);
            }
        }
        return (0, false);
    }

    // 이진 검색을 사용한 EQ 검색 (더 빠름)
    // 소팅된 배열에서 O(log n) 성능
    func (si: *StrIndex) str_search_binary(key: string) -> (i64, bool) {
        let left = 0;
        let right = si.entry_count - 1;

        for left <= right {
            let mid = left + (right - left) / 2;
            let cmp = str_cmp(key, si.entries[mid].key);

            if cmp == 0 {
                return (si.entries[mid].row_id, true);
            }

            if cmp < 0 {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return (0, false);
    }

    // LIKE 검색: 접두어 일치하는 모든 키 검색
    // 반환: ([row_id 배열], 찾은 개수)
    func (si: *StrIndex) str_like(prefix: string) -> ([i64], i32) {
        let result = make([i64], MAX_STR_ENTRIES);
        let result_count = 0;

        let i = 0;
        for i = 0; i < si.entry_count && result_count < MAX_STR_ENTRIES; i = i + 1 {
            if str_starts_with(si.entries[i].key, prefix) {
                result[result_count] = si.entries[i].row_id;
                result_count = result_count + 1;
            }
        }

        return (result, result_count);
    }

    // 범위 검색: from <= key <= to (사전식 순서)
    // 반환: ([row_id 배열], 찾은 개수)
    func (si: *StrIndex) str_range(from: string, to: string) -> ([i64], i32) {
        let result = make([i64], MAX_STR_ENTRIES);
        let result_count = 0;

        let i = 0;
        for i = 0; i < si.entry_count && result_count < MAX_STR_ENTRIES; i = i + 1 {
            let cmp_from = str_cmp(si.entries[i].key, from);
            let cmp_to = str_cmp(si.entries[i].key, to);

            // from <= key && key <= to
            if cmp_from >= 0 && cmp_to <= 0 {
                result[result_count] = si.entries[i].row_id;
                result_count = result_count + 1;
            }
        }

        return (result, result_count);
    }

    // === 삭제 함수 ===

    // 특정 키와 로우 ID를 가진 엔트리 삭제
    // 반환: 성공 여부
    func (si: *StrIndex) str_delete(key: string, row_id: i64) -> bool {
        let pos = -1;
        let i = 0;
        for i = 0; i < si.entry_count; i = i + 1 {
            if si.entries[i].key == key && si.entries[i].row_id == row_id {
                pos = i;
                break;
            }
        }

        if pos == -1 {
            return false;
        }

